import{c as t,Q as a,j as n,m as r}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"From Prefix Cache to Fusion RAG Cache: Accelerating LLM Inference in Retrieval-Augmented Generation","description":"","frontmatter":{"url":"https://arxiv.org/abs/2601.12904","title":"From Prefix Cache to Fusion RAG Cache: Accelerating LLM Inference in Retrieval-Augmented Generation","archived_date":"2026-06-24T00:00:00.000Z","arxiv_id":2601.12904,"authors":["Jiahao Wang","Weiyu Xie","Mingxing Zhang","Boxing Zhang","Jianwei Dong","Yuening Zhu","Chen Lin","Jinqi Tang","Yaochen Han","Zhiyuan Ai","Xianglin Chen","Yongwei Wu","Congfeng Jiang"],"domains":["cs.CL"],"html":"https://arxiv.org/html/2601.12904v1","pdf_path":"pdfs/2601.12904.pdf","published_date":"2026-01-19T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-01-19-prefix-cache-to-fusion-rag-cache-2601-12904.md","filePath":"research/papers/2026-01-19-prefix-cache-to-fusion-rag-cache-2601-12904.md","lastUpdated":1785909234000}'),i={name:"research/papers/2026-01-19-prefix-cache-to-fusion-rag-cache-2601-12904.md"};function o(c,e,s,l,h,g){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="from-prefix-cache-to-fusion-rag-cache-accelerating-llm-inference-in-retrieval-augmented-generation" tabindex="-1">From Prefix Cache to Fusion RAG Cache: Accelerating LLM Inference in Retrieval-Augmented Generation <a class="header-anchor" href="#from-prefix-cache-to-fusion-rag-cache-accelerating-llm-inference-in-retrieval-augmented-generation" aria-label="Permalink to &quot;From Prefix Cache to Fusion RAG Cache: Accelerating LLM Inference in Retrieval-Augmented Generation&quot;">​</a></h1><p><strong>Authors</strong>: Jiahao Wang, Weiyu Xie, Mingxing Zhang, Boxing Zhang, Jianwei Dong, Yuening Zhu, Chen Lin, Jinqi Tang, Yaochen Han, Zhiyuan Ai, Xianglin Chen, Yongwei Wu, Congfeng Jiang <strong>Published</strong>: January 19, 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2601.12904" target="_blank" rel="noreferrer">https://arxiv.org/abs/2601.12904</a> · <a href="https://arxiv.org/html/2601.12904v1" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2601.12904 <strong>Categories</strong>: cs.CL <strong>PDF</strong>: <a href="https://arxiv.org/abs/2601.12904" target="_blank" rel="noreferrer">research/papers/pdfs/2601.12904.pdf</a> (28 pp, full text archived)</p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>Retrieval-Augmented Generation enhances Large Language Models by integrating external knowledge, which reduces hallucinations but increases prompt length. This increase leads to higher computational costs and longer Time to First Token (TTFT). To mitigate this issue, existing solutions aim to reuse the preprocessed KV cache of each retrieved chunk to accelerate RAG. However, the lack of cross-chunk contextual information leads to a significant drop in generation quality, leaving the potential benefits of KV cache reuse largely unfulfilled. The challenge lies in how to reuse the precomputed KV cache of chunks while preserving generation quality. We propose FusionRAG, a novel inference framework that optimizes both the preprocessing and reprocessing stages of RAG. In the offline preprocessing stage, we embed information from other related text chunks into each chunk, while in the online reprocessing stage, we recompute the KV cache for tokens that the model focuses on. As a result, we achieve a better trade-off between generation quality and efficiency. According to our experiments, FusionRAG significantly improves generation quality at the same recomputation ratio compared to previous state-of-the-art solutions. By recomputing fewer than 15% of the tokens, FusionRAG achieves up to 70% higher normalized F1 scores than baselines and reduces TTFT by 2.66x-9.39x compared to Full Attention.</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><ul><li>提出 <strong>FusionRAG</strong>：RAG inference framework，分兩階段解決 KV cache 複用與生成品質的 trade-off 問題</li><li><strong>Offline preprocessing</strong>：將相關 chunk 的資訊嵌入（embed）到各 chunk，補全 cross-chunk contextual information</li><li><strong>Online reprocessing</strong>：選擇性重算模型「關注」token 的 KV cache（selective recomputation），以最小代價恢復品質</li><li>系統性分析了從 prefix cache 到 RAG-specific cache 的設計空間，提煉出 FusionRAG 架構</li></ul><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li>重算 &lt;15% token 的情況下，normalized F1 score 較 baseline 提升最高 <strong>70%</strong></li><li>TTFT 比 Full Attention 減少 <strong>2.66x–9.39x</strong></li><li>相同 recomputation ratio 下，生成品質顯著優於先前 state-of-the-art 方案</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><ul><li>論文未列明確 limitation 章節</li><li>判斷弱點：offline preprocessing 需預先建立 chunk fusion index，增加儲存與 pipeline 複雜度；selective recomputation 的 token 選擇策略依賴 attention pattern，在 streaming 或 long-context 場景的穩健性有待驗證；實驗結果依特定 RAG benchmark，跨域泛化性未完整評估</li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li><strong>Prompt caching / context-management</strong>：FusionRAG 的 KV cache 複用策略與 <code>context-management.md</code> 的 Prompt Caching 核心原則高度對應——「Static First」前綴快取 + 動態 token 選擇性重算，正是 NLAH（Right context &gt; more context）的推論層實踐；可作為理解快取設計取捨的參考文獻</li><li><strong>Token budget / TTFT</strong>：論文量化了 RAG prompt 長度增長對 TTFT 的成本衝擊，呼應 <code>context-management.md</code> token budget 管理的動機——長 RAG context 若不加管控，與 workspace 中 &gt;70% 觸發 compact 的行為信號同屬「context 超支」問題</li><li><strong>OBSERVE 階段 / 工具輸出截斷</strong>：FusionRAG selective recomputation 的「只看模型真正 attend 的部分」與 core.md OBSERVE「工具輸出被截斷時不得假設截斷後為空」在設計哲學上互通——兩者都強調不能靜默丟棄低注意力區域的資訊</li><li>⚠️ 落地門檻：FusionRAG 需修改 inference engine KV cache 層，在本 workspace 的 prompt engineering / agent orchestration 層無法直接採用；概念層可借鑑，實作層需獨立工程投入</li></ul>',16)])])}const d=t(i,[["render",o]]);export{p as __pageData,d as default};
